#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
#
# G022 memory scorer: peak and post-idle RssAnon per replay run, from each
# run dir's run.log ("peak RssAnon <kB> kB over ..." and
# "post-idle: RssAnon <kB> kB 45 s after the end; ..." lines).
# Usage: mem_score.py <runs dir> <prefix>... --pair ARM/BASE ...
#   e.g. mem_score.py runs g22r1_ g22r2_ g22m --pair CpTW/Cp --pair N9/A
# A run dir name is <prefix><arm> or g22m<n>_<arm>; the arm is the part
# after the last underscore.
import os, re, sys, statistics

PEAK = re.compile(r'peak RssAnon (\d+) kB over (\d+) samples')
IDLE = re.compile(r'post-idle: RssAnon (\d+) kB 45 s after the end; height (\d+)')

def main(argv):
    pairs, rest = [], []
    it = iter(argv)
    for a in it:
        if a == '--pair':
            pairs.append(tuple(next(it).split('/')))
        else:
            rest.append(a)
    runs_dir, prefixes = rest[0], rest[1:]
    data = {}  # arm -> list of (run, peak, idle)
    for name in sorted(os.listdir(runs_dir)):
        if not any(name.startswith(p) for p in prefixes):
            continue
        log = os.path.join(runs_dir, name, 'run.log')
        if not os.path.isfile(log):
            continue
        txt = open(log, errors='replace').read()
        p, i = PEAK.search(txt), IDLE.search(txt)
        arm = name.rsplit('_', 1)[1]
        peak = int(p.group(1)) if p else None
        idle = int(i.group(1)) if i else None
        print(f'{name:12s} arm {arm:5s} peak {peak} kB  post-idle {idle} kB')
        data.setdefault(arm, []).append((name, peak, idle))
    print()
    stats = {}
    for arm, rows in sorted(data.items()):
        out = []
        for k, label in ((1, 'peak'), (2, 'post-idle')):
            v = [r[k] for r in rows if r[k] is not None]
            if not v:
                out.append(f'{label} n/a'); continue
            m = statistics.median(v)
            stats[(arm, label)] = (m, min(v), max(v))
            out.append(f'{label} median {m/1024:.0f} MB [{min(v)/1024:.0f}-{max(v)/1024:.0f}] n={len(v)}')
        print(f'{arm:5s} ' + '; '.join(out))
    print()
    for arm, base in pairs:
        for label in ('peak', 'post-idle'):
            a, b = stats.get((arm, label)), stats.get((base, label))
            if not a or not b:
                print(f'{arm}/{base} {label}: missing'); continue
            r = a[0] / b[0]
            ov = 'overlap' if (a[1] <= b[2] and b[1] <= a[2]) else 'no overlap'
            print(f'{arm}/{base} {label}: ratio {r:.3f} ({(r-1)*100:+.1f}%), {ov}')

if __name__ == '__main__':
    main(sys.argv[1:])
